    spdlog::error("sys_call: stat failed: path='{}': {}", filename,
                  std::strerror(errno));
  } else {
    target_stat->st_size = temp_stat.st_size;
    target_stat->st_mode = temp_stat.st_mode;
  }
  return ret;
};
uint64_t handle_openat(uint64_t a0 __attribute__((unused)),
                       uint64_t a1 __attribute__((unused)),
                       uint64_t a2 __attribute__((unused)),
                       uint64_t a3 __attribute__((unused)),
                       uint64_t a4 __attribute__((unused)),
                       uint64_t a5 __attribute__((unused)),
                       uint64_t a6 __attribute__((unused)))
{
