17	#include <cstdint>
18	
19	#include <span>
20	
21	static constexpr uint64_t HTIF_PUTCHAR_OFFSET = 0x4;
22	static constexpr uint64_t HTIF_CMD_OFFSET = 0x10;
23	static constexpr uint64_t HTIF_CMD_HIGH_OFFSET = 0x14;
24	static constexpr uint64_t INT_TRIGGER_OFFSET = 0x20;
25	
26	extern sc_core::sc_semaphore custom_master_sem;
27	extern SubPortTest subport_test;
28	
29	enum class SimCommand : uint32_t
30	{
31	  FINISHED = 0x01234567,
32	  PASSED = 0x01234568,
33	  FAILED = 0x01234569,
34	  WARNING = 0x01234570,
35	  SKIPPED = 0x01234571,
36	  NEWLINE = 0xddddeeee,
37	  // below are for tests only
38	  TEST_ILM = 0x00abcde0,
39	  TEST_DLM = 0x00abcde1,
40	  TEST_HVM = 0x00abcde2,
41	};
42	
43	constexpr size_t SYSCALL_TABLE_SIZE = 100;
44	constexpr size_t MAGIC_MEM_SIZE = 8;
45	constexpr int HTIF_32BIT_PARTS = 2;
46	
47	template<std::size_t BusWidth = 32>
48	class SimControl : public sc_core::sc_module
49	{
50	public:
51	  using sys_func_ptr = uint64_t (SimControl::*)(
52	    uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);
53	
54	  tlm_utils::simple_target_socket<SimControl, BusWidth> socket{"tsck"};
55	  int32_t exits;
56	  const MemoryRegion region;
57	
58	  SimControl(const sc_core::sc_module_name& name,
59	             const MemoryRegion& region,
60	             SimpleMemory<BusWidth>& main_memory,
61	             sc_core::sc_signal<sc_dt::sc_uint<31>>& int_trigger,
62	             const sc_core::sc_clock& clk)
63	      : sc_core::sc_module{name},
64	        exits(-1),
65	        region(region),
66	        data_region(main_memory),
67	        int_trigger(int_trigger),
68	        clk(clk),
69	        riscv_xlen(0),
70	        partial_htif_command(0),
71	        htif_parts_received(0)
72	  {
73	    sim_syscall_table[5] = &SimControl::handle_gettimeofday;
74	    sim_syscall_table[6] = &SimControl::handle_open;
75	    sim_syscall_table[7] = &SimControl::handle_write;
76	    sim_syscall_table[8] = &SimControl::handle_getcwd;
77	    sim_syscall_table[9] = &SimControl::handle_lseek;
78	    sim_syscall_table[10] = &SimControl::handle_read;
79	    sim_syscall_table[11] = &SimControl::handle_flen;
80	    sim_syscall_table[12] = &SimControl::handle_close;
81	    sim_syscall_table[13] = &SimControl::handle_access;
82	    sim_syscall_table[14] = &SimControl::handle_faccessat;
83	    sim_syscall_table[15] = &SimControl::handle_fstat;
84	    sim_syscall_table[16] = &SimControl::handle_fstatat;
85	    sim_syscall_table[17] = &SimControl::handle_link;
86	    sim_syscall_table[18] = &SimControl::handle_lstat;
87	    sim_syscall_table[19] = &SimControl::handle_stat;
88	    sim_syscall_table[20] = &SimControl::handle_openat;
89	    sim_syscall_table[21] = &SimControl::handle_rename;
90	    sim_syscall_table[22] = &SimControl::handle_unlink;
91	
92	    this->socket.register_b_transport(this, &SimControl::b_transport);
93	  }
94	
95	  void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& /*delay*/)
96	  {
97	    handle_trans(trans);
98	    trans.set_response_status(tlm::TLM_OK_RESPONSE);
99	  }
100	
101	#if ENABLE_PYBIND11
102	  static void bind_pybind11(pybind11::module_& m)
103	  {
104	    char namebuf[30];
105	    snprintf(namebuf, sizeof(namebuf), "sim_control_%zu", BusWidth);
106	    pybind11::class_<SimControl>(m, namebuf)
107	      .def_readwrite("exits", &SimControl::exits);
108	  }
109	#endif
110	
111	#include "htif/sys_call.hpp"
112	
113	private:
114	  SimpleMemory<BusWidth>& data_region;
115	  sc_core::sc_signal<sc_dt::sc_uint<31>>& int_trigger;
116	  const sc_core::sc_clock& clk;
117	  sys_func_ptr sim_syscall_table[SYSCALL_TABLE_SIZE] = {};
118	  uint32_t riscv_xlen;
119	  uint64_t partial_htif_command;
120	  int htif_parts_received;
121	
122	  void handle_trans(tlm::tlm_generic_payload& trans)
123	  {
124	    const auto addr = trans.get_address();
125	    const auto len = trans.get_data_length();
126	    const auto buf = std::span{trans.get_data_ptr(), len};
127	    const auto offset = addr - region.base_address;
128	
129	    if (trans.is_read()) {
130	      spdlog::debug("sim_control: read, addr={:#x}, len={}", addr, len);
131	      return;
132	    }
133	
134	    spdlog::debug("sim_control: write, addr={:#x}, len={}", addr, len);
135	
136	    if (offset == 0 && len == 4) {
137	      handle_sim_command(unpack<uint32_t>(buf));
138	    } else if (offset == HTIF_PUTCHAR_OFFSET && len == 1) {
139	      std::putchar(buf[0]);
140	    } else if (offset == HTIF_CMD_OFFSET) {
141	      (len == 8) ? handle_htif_64bit_write(buf)
142	                 : handle_htif_32bit_low_write(buf);
143	    } else if (offset == HTIF_CMD_HIGH_OFFSET && len == 4) {
144	      handle_htif_32bit_high_write(buf);
145	    } else if (offset == INT_TRIGGER_OFFSET && len == 4) {
146	      auto val = unpack<uint32_t>(buf);
147	      spdlog::debug("sim_control: int_trigger = {:#x}", val);
148	      int_trigger.write(val);
149	      // clear the IRQ after one cycle
150	      if (val != 0) {
151	        wait(clk.posedge_event());
152	        int_trigger.write(0);
153	      }
154	    } else {
155	      spdlog::warn("sim_control: spurious write at {:#x}, length {}", addr,
156	                   len);
157	    }
158	  }
159	
160	  void handle_sim_command(uint32_t command)
161	  {
162	    spdlog::info("sim_control: received command {:#x}", command);
163	    switch (static_cast<SimCommand>(command)) {
164	    case SimCommand::NEWLINE:
165	      std::putchar('\n');
166	      break;
167	    case SimCommand::TEST_ILM:
168	      subport_test = SubPortTest::TEST_ILM;
169	      custom_master_sem.post();
170	      break;
171	    case SimCommand::TEST_DLM:
172	      subport_test = SubPortTest::TEST_DLM;
173	      custom_master_sem.post();
174	      break;
175	    case SimCommand::TEST_HVM:
176	      subport_test = SubPortTest::TEST_HVM;
177	      custom_master_sem.post();
178	      break;
179	    case SimCommand::PASSED:
180	    case SimCommand::FINISHED:
181	      spdlog::info("sim_control: Test PASSED");
182	      exits = 0;
183	      break;
184	    case SimCommand::SKIPPED:
185	      spdlog::info("sim_control: Test SKIPPED");
186	      exits = 0;
187	      break;
188	    case SimCommand::FAILED:
189	      spdlog::info("sim_control: Test FAILED");
190	      exits = 1;
191	      break;
192	    case SimCommand::WARNING:
193	      spdlog::warn("sim_control: Test WARNING");
194	      exits = 1;
195	      break;
196	    default:
197	      if (command < 256)
198	        exits = command;
199	      else
200	        spdlog::warn("sim_control: unknown command {:#x}", command);
201	      break;
202	    }
203	  }
204	
205	  template<typename T>
206	  static T unpack(const std::span<uint8_t>& buf)
207	  {
208	    T result = 0;
209	    for (size_t i = 0; i < sizeof(T); ++i)
210	      result |= static_cast<T>(buf[i]) << (i * 8);
211	    return result;
212	  }
213	
214	  void execute_htif_syscall()
215	  {
216	    command_t cmd(partial_htif_command);
217	    if (cmd.device() != 0 || cmd.cmd() != 0) {
218	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
219	      return;
220	    }
221	    dispatch(cmd);
222	    partial_htif_command = 0;
223	    htif_parts_received = 0;
224	  }
225	
226	  void handle_htif_64bit_write(const std::span<uint8_t>& buf)
227	  {
228	    command_t cmd(unpack<uint64_t>(buf));
229	    if (cmd.device() == 0 && cmd.cmd() == 0)
230	      dispatch(cmd);
231	    else
232	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
233	  }
234	
235	  void handle_htif_32bit_low_write(const std::span<uint8_t>& buf)
236	  {
237	    partial_htif_command |= unpack<uint32_t>(buf);
238	    if (++htif_parts_received == HTIF_32BIT_PARTS)
239	      execute_htif_syscall();
240	  }
241	
242	  void handle_htif_32bit_high_write(const std::span<uint8_t>& buf)
243	  {
244	    partial_htif_command |= static_cast<uint64_t>(unpack<uint32_t>(buf)) << 32;
245	    if (++htif_parts_received == HTIF_32BIT_PARTS)
246	      execute_htif_syscall();
247	  }
248	
249	  void dispatch(command_t cmd)
250	  {
251	    uint64_t syscall_args[MAGIC_MEM_SIZE];
252	    auto addr_offset = cmd.payload() - data_region.region.base_address;
253	    auto src = data_region.data.begin() + addr_offset;
254	
255	    std::copy(src, src + sizeof(syscall_args),
256	              reinterpret_cast<uint8_t*>(syscall_args));
257	
258	    spdlog::debug("sim_control: args: {:#x}, {:#x}, {:#x}, "
259	                  "{:#x}, {:#x}, {:#x}, {:#x}",
260	                  syscall_args[0], syscall_args[1], syscall_args[2],
261	                  syscall_args[3], syscall_args[4], syscall_args[5],
262	                  syscall_args[6]);
263	
264	    auto syscall_num = syscall_args[0];
265	    if (syscall_num >= SYSCALL_TABLE_SIZE || !sim_syscall_table[syscall_num]) {
266	      spdlog::critical("sim_control: invalid syscall number {}", syscall_num);
267	      syscall_args[0] = static_cast<uint64_t>(-1);
268	    } else {
269	      syscall_args[0] = (this->*sim_syscall_table[syscall_num])(
270	        syscall_args[1], syscall_args[2], syscall_args[3], syscall_args[4],
271	        syscall_args[5], syscall_args[6], syscall_args[7]);
272	    }
273	
274	    std::copy(reinterpret_cast<uint8_t*>(syscall_args),
275	              reinterpret_cast<uint8_t*>(syscall_args) + sizeof(syscall_args),
276	              src);
277	  }
278	};
